<script setup>
import { computed, onMounted, ref, watch } from 'vue'
const key='zoocare_care_records', items=ref([]), animals=ref([]), search=ref(''), showForm=ref(false), editing=ref(null), message=ref('')
const empty=()=>({animal:'',date:new Date().toISOString().slice(0,10),type:'Feeding',staff:'',notes:'',status:'Completed'}), form=ref(empty())
onMounted(()=>{items.value=JSON.parse(localStorage.getItem(key)||'[]');animals.value=JSON.parse(localStorage.getItem('zoocare_animals')||'[]')})
watch(items,v=>localStorage.setItem(key,JSON.stringify(v)),{deep:true})
const filtered=computed(()=>items.value.filter(r=>[r.animal,r.date,r.type,r.staff,r.notes,r.status].join(' ').toLowerCase().includes(search.value.toLowerCase())))
function openAdd(){animals.value=JSON.parse(localStorage.getItem('zoocare_animals')||'[]');editing.value=null;form.value=empty();showForm.value=true;message.value=''}
function edit(r){editing.value=r.id;form.value={...r};showForm.value=true;message.value=''}
function save(){if(!form.value.animal){message.value='Please enter an animal name.';return}const data={...form.value};if(editing.value!==null){const i=items.value.findIndex(r=>r.id===editing.value);items.value[i]={...data,id:editing.value}}else items.value.push({...data,id:Date.now()});showForm.value=false;message.value='Care record saved successfully.'}
function remove(id){if(confirm('Delete this care record?'))items.value=items.value.filter(r=>r.id!==id)}
</script>
<template><div class="page-title-row"><div><p class="eyebrow">ANIMAL WELLNESS</p><h1>Care Records</h1><p class="muted">Record feeding, checkups, treatments, and other care activities.</p></div><button class="btn btn-primary" @click="openAdd">+ Add care record</button></div><div class="toolbar"><input v-model="search" class="search-input" placeholder="Search animal, date, activity, or staff..."><span class="result-count">{{ filtered.length }} records</span></div><div v-if="showForm" class="form-panel"><div class="panel-heading"><h2>{{ editing!==null?'Edit care record':'Add care record' }}</h2><button class="icon-button" @click="showForm=false">Close</button></div><form @submit.prevent="save" class="form-grid"><label>Animal name<select v-model="form.animal" required><option value="" disabled>Select an animal</option><option v-for="a in animals" :key="a.id" :value="a.name">{{ a.name }} — {{ a.species }}</option></select><input v-if="!animals.length" v-model="form.animal" placeholder="No animals registered: enter name" required></label><label>Date<input v-model="form.date" type="date" required></label><label>Care activity<select v-model="form.type"><option>Feeding</option><option>Health checkup</option><option>Treatment</option><option>Cleaning</option><option>Other</option></select></label><label>Staff member<input v-model="form.staff" placeholder="Staff name"></label><label>Status<select v-model="form.status"><option>Completed</option><option>Pending</option><option>In progress</option></select></label><label>Notes<input v-model="form.notes" placeholder="Care notes"></label><div class="form-actions"><button class="btn btn-primary" type="submit">Save record</button><span class="form-message">{{ message }}</span></div></form></div><div class="table-card"><table><thead><tr><th>ANIMAL</th><th>DATE</th><th>ACTIVITY</th><th>STAFF</th><th>STATUS</th><th>NOTES</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><strong>{{ r.animal }}</strong></td><td>{{ r.date }}</td><td>{{ r.type }}</td><td>{{ r.staff||'—' }}</td><td><span class="pill" :class="r.status==='Pending'?'occupied':''">{{ r.status }}</span></td><td>{{ r.notes||'—' }}</td><td><div class="actions"><button class="action-link" @click="edit(r)">Edit</button><button class="action-link danger" @click="remove(r.id)">Delete</button></div></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty-state">No care records found. Add a record to get started.</td></tr></tbody></table></div></template>
